sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') return;

    var ga = new GlideAjax('x_1777185_home_s_0.GetCustomerDetails');
    ga.addParam('sysparm_name', 'getDetails');
    ga.addParam('sysparm_customer_id', newValue);
    ga.getXML(getrDetails);

    function getrDetails(response) {
        var data = response.responseXML.documentElement.getAttribute("answer");
        var ans = JSON.parse(data);
        if (ans) {
            g_form.setValue('email', ans.email);
            g_form.setValue('contact_number', ans.contact_number);
            g_form.setValue('street_line_1', ans.street_line_1);
            g_form.setValue('street_line_2', ans.street_line_2);
            g_form.setValue('street_line_3', ans.street_line_3);
            g_form.setValue('district', ans.district);
            g_form.setValue('city', ans.city);
            g_form.setValue('state_or_province', ans.state);
            g_form.setValue('pin_code', ans.pin_code);
        }
    }
}
